sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {},

    isDatePast: function(when_needed_str) {
        var rightNow = new GlideDateTime();
        var whenNeeded = new GlideDateTime(when_needed_str);

        if (whenNeeded.before(rightNow)) {
            return true;
        }
        return false;
    },

    isDateToday: function(when_needed_str) {

        var rightNow = new GlideDateTime();
        var when_needed = new GlideDateTime(when_needed_str);

        var rightNowDate = rightNow.getLocalDate();
        var whenNeededDate = when_needed.getLocalDate();

        if (rightNowDate.compareTo(whenNeededDate) == 0) {
            return true;

        }
        return false;
    },



    type: 'NeedItUtils'
};
